// countStaleEndedSessions returns the number of ENDED sessions that are not
// yet FullyCondensed. These sessions are re-processed on every PostCommit until
// they are cleaned up via `entire clean --force`.
func countStaleEndedSessions(sessions []*SessionState) int {
	count := 0
	for _, s := range sessions {
		if s.Phase == session.PhaseEnded && !s.FullyCondensed {
			count++
		}
	}
	return count
}
```

