```go
const (
	// staleEndedSessionWarnThreshold is the minimum number of stale ENDED
	// sessions before a warning is shown. Below this, accumulation is minor.
	staleEndedSessionWarnThreshold = 3

	// staleEndedSessionWarnInterval is how often the warning can fire.
	staleEndedSessionWarnInterval = 24 * time.Hour

	// staleEndedSessionWarnFile is the rate-limit sentinel inside .git/entire-sessions/.
	staleEndedSessionWarnFile = ".warn-stale-ended"
)

// warnStaleEndedSessions emits a rate-limited stderr warning when ENDED sessions
// are accumulating. Each stale session costs ~73-103ms per PostCommit invocation.
func warnStaleEndedSessions(ctx context.Context, count int, worktreePath string) {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	store, err := session.NewStateStore(filepath.Join(worktreePath, ".git", "entire-sessions"))
	if err != nil {
		logging.Debug(logCtx, "warn stale: could not open state store", slog.String("error", err.Error()))
		return
	}

	warnFile := filepath.Join(store.Dir(), staleEndedSessionWarnFile)
	if info, err := os.Stat(warnFile); err == nil {
		if time.Since(info.ModTime()) < staleEndedSessionWarnInterval {
			return // rate-limited
		}
	}

	// Update rate-limit file (best-effort — don't fail if this errors)
	//nolint:errcheck,gosec
	_ = os.WriteFile(warnFile, []byte{}, 0o644)

	fmt.Fprintf(os.Stderr,
		"\nentire: %d ended session(s) are still being processed on each commit.\n"+
			"Run 'entire clean --force' to remove them and restore commit performance.\n\n",
		count,
	)
}
```

**Note on imports:** Add `"os"` and `"fmt"` to the import block if not already present. Also add `"path/filepath"` and `"time"`. Check `.golangci.yml` for any linter restrictions on `fmt.Fprintf(os.Stderr, ...)` in hook code — if the codebase prefers `cmd.ErrOrStderr()`, adapt accordingly; but hooks don't have a cobra `cmd` in scope here so `os.Stderr` is correct.

