// TestWarnStaleEndedSessions_RateLimit verifies the warning fires at threshold
// and respects the 24h rate limit.
func TestWarnStaleEndedSessions_RateLimit(t *testing.T) {
	t.Parallel()
	dir := setupGitRepo(t)
	t.Chdir(dir)

	sessions := []*SessionState{
		{Phase: session.PhaseEnded, FullyCondensed: false},
		{Phase: session.PhaseEnded, FullyCondensed: false},
		{Phase: session.PhaseEnded, FullyCondensed: false},
	}

	// Below threshold — no warning file created
	twoStale := sessions[:2]
	assert.Equal(t, 0, countStaleEndedSessions(twoStale[:0]))
	assert.Equal(t, 2, countStaleEndedSessions(twoStale))

	// At threshold — warning should fire, creating rate-limit file
	ctx := context.Background()
	warnStaleEndedSessions(ctx, 3, dir)

	warnFile := filepath.Join(dir, ".git", "entire-sessions", staleEndedSessionWarnFile)
	_, err := os.Stat(warnFile)
	assert.NoError(t, err, "rate-limit file must be created after warning fires")

	// Second call within interval — rate-limit file exists, no duplicate warning
	// (We can't easily assert stderr here without capturing it, but we verify
	// the function does not panic and the file mtime is preserved.)
	before, _ := os.Stat(warnFile)
	warnStaleEndedSessions(ctx, 3, dir)
	after, _ := os.Stat(warnFile)
	assert.Equal(t, before.ModTime(), after.ModTime(), "mtime must not change on rate-limited call")
}
