```go
const (
	// staleEndedSessionWarnThreshold is the minimum count of stale ENDED sessions
	// before a warning is shown.
	staleEndedSessionWarnThreshold = 3

	// staleEndedSessionWarnInterval is how often the same warning can be shown.
	staleEndedSessionWarnInterval = 24 * time.Hour

	// staleEndedSessionWarnFile is the rate-limit sentinel filename inside the
	// git common dir's entire-sessions directory.
	staleEndedSessionWarnFile = ".warn-stale-ended"
)

// warnStaleEndedSessions emits a rate-limited stderr warning when stale ENDED
// sessions are accumulating. Each stale session costs ~73-103ms per PostCommit.
// Rate-limited to once per staleEndedSessionWarnInterval via a sentinel file.
func warnStaleEndedSessions(ctx context.Context, count int) {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Use GetGitCommonDir (not worktreePath) so linked worktrees resolve correctly.
	commonDir, err := GetGitCommonDir(ctx)
	if err != nil {
		logging.Debug(logCtx, "warn stale: could not get git common dir",
			slog.String("error", err.Error()))
		return
	}

	warnFile := filepath.Join(commonDir, session.SessionStateDirName, staleEndedSessionWarnFile)

	// Check rate limit
	if info, statErr := os.Stat(warnFile); statErr == nil {
		if time.Since(info.ModTime()) < staleEndedSessionWarnInterval {
			return
		}
	}

	// Update rate-limit file (best-effort)
	//nolint:errcheck,gosec
	_ = os.WriteFile(warnFile, []byte{}, 0o644)

	fmt.Fprintf(os.Stderr,
		"\nentire: %d ended session(s) are still being processed on each commit.\n"+
			"Run 'entire clean --force' to remove them and restore commit performance.\n\n",
		count,
